contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    // Allow receiving Ether when c.withdrawAll sends funds
    receive() external payable { }

    // Single public test function: depositAmount to send to c
    function run(uint depositAmount) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (depositAmount)); require(depositAmount <= 1000000000000000000000000000000);
        // Must have enough Ether in this contract to deposit
        require(address(this).balance >= depositAmount, "insufficient balance for deposit");

        // Record contract balance of C before any action
        uint beforeCBalance = address(c).balance;

        // Perform deposit of the specified amount
        c.deposit{value: depositAmount}(); if (__ESBMC_reverted()) return;

        // Balance of C after deposit
        uint afterDepositCBalance = address(c).balance;

        // The amount that should have increased is depositAmount; require that to avoid trivial cases
        require(afterDepositCBalance >= beforeCBalance);

        // Try withdrawAll and record whether it reverted
        bool reverted;
        c.withdrawAll(); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        // Balance of C after withdraw attempt
        uint finalCBalance = address(c).balance;

        // If withdrawAll reverted, C's balance must equal afterDepositCBalance.
        // If it succeeded, then C's balance must have decreased by at most afterDepositCBalance - beforeCBalance
        // and by exactly the previous recorded credit for this caller. Since we cannot read the mapping directly,
        // we observe that the only source of funds to the caller is via withdrawAll transferring some amount up to the deposited amount.
        // We assert the explicit observable law: either no change on revert, or the decrease equals the amount received by this contract.

        // Determine how much Ether this test contract received from the withdraw (final balance - balance just after deposit sendings to c)
        // Note: address(this).balance changed when we sent the deposit; compute expected receive amount by comparing address(this).balance now to what it would be.

        // Compute this contract's balance at three points isn't directly stored earlier; instead, infer received = (afterDepositCBalance - finalCBalance) when withdraw succeeded.

        // Build assertion:
        assert(
            (reverted && finalCBalance == afterDepositCBalance)
            || (!reverted && afterDepositCBalance >= finalCBalance && afterDepositCBalance - finalCBalance <= depositAmount)
        );
    }
}

